// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(0) && _target != address(c) && _target != msg.sender);
        _value = bound(_value, 0, 100 ether);
        vm.deal(address(c), 1000 ether);
        uint256 senderBalanceBefore = address(msg.sender).balance;
        c.sendMoney(_target, _value);
        uint256 senderBalanceAfter = address(msg.sender).balance;
        assertTrue(senderBalanceAfter == senderBalanceBefore);
    }
}

